$window=[Windows.Markup.XamlReader]::Parse($layout)
foreach ($n in 'Tabs','Admin','Status','Reload','Review','First','Second','Search','Choice','EdgeCost','SetEdge','ResetEdge','Routes','PageTitle','Powder','Example','NavPowder','NavDefaults','NavRoutes','NavPokemon','NavPets','NavOutfits') {
