function M.createGallery()
-- Native catalog view. Preview entries describe pictures; the engine owns reward eligibility.
local G={}
local kinds={"outfit","pet","pokemon"}
local tab, page, active=1,1,false
local positions={}
local layoutPositions
local compactGrid
local engine, extras, session, atlas
local bundled, cacheDir
local rows, levels
local families, memberFamily, species = {}, {}, {}
local sizes,picked
local query, detail, results = "", nil, {}
local generation, generationMenuOpen = 0, false
local generations = {[0]={label="모두"}, {label="1세대", first=1, last=151},
                     {label="2세대", first=152, last=251}}
local generationLayout
local editorFile, editorRunning, focusPending, editorSequence
local focusEpoch,clearGeneration=0,0
local request,retryAction
local editorInstance=tostring({}):gsub("[^%w]","")..os.time()
local panelX, panelY = 0, 0

local function dex(number)
    return string.format("#%04d",number)
end

local function sizeSuffix(id)
    local tier=sizes.tiers[sizes.species[id]]
    return tier and (" · "..tier.label) or ""
end

local function matches(item,needle)
    if needle=="" then return true end
    local number=needle:match("^#?(%d+)$")
    if number then return tonumber(number)==item.dex end
    return item.id:lower():find(needle,1,true) or (item.name or item.id):lower():find(needle,1,true)
end

-- Lua passes strings to Rainmeter in the Windows code page. Character references
-- let the native meters render UTF-8 catalog labels on any system locale.
local function nativeText(value)
    return (value:gsub("[\128-\255][\128-\191]*",function(char)
        local a,b,c=char:byte(1,3)
        local code
        if #char==2 and a<224 then code=(a-192)*64+b-128
        elseif #char==3 and a<240 then code=((a-224)*64+b-128)*64+c-128 end
        return code and string.format("[\\x%04x]",code) or "?"
    end))
end

local function setting(meter, option, value)
    if option=="Text" or option=="ToolTipText" then value=nativeText(value) end
    SKIN:Bang("!SetOption",meter,option,tostring(value))
end

local function visible(name,yes)
    SKIN:Bang(yes and "!ShowMeter" or "!HideMeter",name)
end

-- Pixel button backgrounds are painted on existing Shape meters so older hosts
-- receive the same controls through a catalog-only update.
local palette={
    idle={"66,83,75","231,229,203","253,249,223"},
    selected={"43,78,66","161,211,174","211,238,197"},
    action={"95,68,37","246,196,113","255,226,162"},
    dark={"24,44,46","70,103,99","96,137,127"},
    muted={"152,158,141","219,220,205","234,234,220"},
    owned={"82,115,89","225,237,211","247,248,222"},
    locked={"141,152,138","230,229,217","247,244,228"}
}
local painted={}
local function paint(meter,first,x,y,w,h,style)
    local key=meter..":"..first
    local signature=table.concat({x,y,w,h,style or "none"},",")
    if painted[key]==signature then return end
    painted[key]=signature
    local function shape(i,value)
        local n=first+i
        setting(meter,n==1 and "Shape" or "Shape"..n,value)
    end
    if not style then
        for i=0,2 do shape(i,"Rectangle 0,0,0,0 | StrokeWidth 0") end
        return
    end
    local colors=palette[style]
    local function stepped(i,dx,dy,ww,hh,corner,color)
        local left,top=x+dx,y+dy
        local right,bottom=left+ww,top+hh
        local p=string.format("%d,%d",left+corner,top)
        for _,point in ipairs({{right-corner,top},{right-corner,top+corner},{right,top+corner},
            {right,bottom-corner},{right-corner,bottom-corner},{right-corner,bottom},
            {left+corner,bottom},{left+corner,bottom-corner},{left,bottom-corner},
            {left,top+corner},{left+corner,top+corner}}) do
            p=p..string.format(" | LineTo %d,%d",point[1],point[2])
        end
        local name="PixelPath"..(first+i)
        setting(meter,name,p.." | ClosePath 1")
        shape(i,"Path "..name.." | StrokeWidth 0 | Fill Color "..color)
    end
    stepped(0,0,0,w,h,3,colors[1])
    stepped(1,1,1,w-2,h-4,2,colors[2])
    shape(2,string.format("Rectangle %d,%d,%d,1 | StrokeWidth 0 | Fill Color %s",x+4,y+2,w-8,colors[3]))
end

local buttonLayout={
    {"GalleryBack",155,9,72,25},{"GalleryClose",270,9,46,25},
    {"GalleryPrev",105,415,29,25},{"GalleryPageNumber",137,415,62,25},
    {"GalleryNext",202,415,29,25},{"GalleryUpdates",237,415,79,25}
}
local function placeButtons()
    for _,b in ipairs(buttonLayout) do
        local name,x,y,w,h=unpack(b)
        setting(name,"X",panelX+x+math.floor(w/2))
        setting(name,"Y",panelY+y)
        setting(name,"W",w)
        setting(name,"H",h-4)
        setting(name,"Padding","0,4,0,0")
        setting(name,"StringAlign","Center")
        setting(name,"FontSize",9)
        setting(name,"SolidColor","0,0,0,1")
        setting(name,"FontColor",y<40 and "255,250,225" or "44,61,53")
    end
end
local function drawButtons(isDetail,pageNumber,pageCount,follow,canEvolve,hasRule)
    for i=1,3 do
        paint("GalleryCard",4+(i-1)*3,13+(i-1)*103,54,96,30,i==tab and "selected" or "idle")
        setting("GalleryTabBg"..i,"SolidColor","0,0,0,1")
    end
    local styles={"dark","dark",not isDetail and pageNumber>1 and "idle",
        isDetail and (follow and "selected" or hasRule and (canEvolve and "action" or "muted"))
            or not isDetail and pageCount>1 and "idle",
        not isDetail and pageNumber<pageCount and "idle",not generationMenuOpen and "idle"}
    for i,b in ipairs(buttonLayout) do
        paint("GalleryCard",13+(i-1)*3,b[2],b[3],b[4],b[5],styles[i])
    end
end


local function catalogRows()
    rows={outfit={},pet={},pokemon={}}
    levels={}
    local indexed={}
    for _,item in ipairs(engine.gallery or {}) do
        if rows[item.kind] then
            table.insert(rows[item.kind],item)
            indexed[item.id]=true
        end
    end
    for _,list in ipairs({engine.catalog or {},extras}) do
        for _,item in ipairs(list) do
            if rows[item.kind] then
                levels[item.id]=item.level
                if not indexed[item.id] then
                    table.insert(rows[item.kind],item)
                    indexed[item.id]=true
                end
            end
        end
    end
    for i,item in ipairs(rows.pokemon) do
        local mon=species[item.id]
        rows.pokemon[i]={id=item.id,kind="pokemon",name=mon and mon[3] or item.name,
                         dex=mon and mon[1] or tonumber(item.dex),icon=item.icon}
    end
    table.sort(rows.pokemon,function(a,b)
        local left,right=a.dex or math.huge,b.dex or math.huge
        if left==right then return a.id<b.id end
        return left<right
    end)
end

local function imagePath()
    return engine.imageFile(cacheDir,"unlock-gallery",engine.atlas,bundled)
end

local function place(x,y)
    for name,pos in pairs(positions) do
        setting(name,"X",x and x+pos[1] or 0)
        setting(name,"Y",y and y+pos[2] or 0)
    end
    compactGrid,generationLayout=nil,nil
end

-- List and evolution detail are mutually exclusive. Reuse the four detail labels
-- already present in installed skins, so a catalog update can supply the full menu.
local function layoutGenerationMenu(show)
    if generationLayout==show then return end
    generationLayout=show
    for i=0,3 do
        local name="GalleryEvolution"..(6+i)
        local pos=positions[name]
        local y=positions.GallerySearchFrame[2]
        setting(name,"X",panelX+(show and 237 or pos[1]))
        setting(name,"Y",panelY+(show and (i==0 and y or y+29+(i-1)*17) or pos[2]))
        setting(name,"W",show and 70 or 286)
        setting(name,"H",show and (i==0 and 23 or 17) or 25)
        setting(name,"Padding",show and (i==0 and "7,5,0,0" or "7,0,0,0") or "0,0,0,0")
        setting(name,"FontFace",show and "Malgun Gothic" or "Galmuri9 Regular")
        setting(name,"FontSize",show and 9 or 10)
        setting(name,"AntiAlias",show and 1 or 0)
        setting(name,"MouseScrollUpAction",show and '[!CommandMeasure AvatarUnlocks "GalleryScrollGeneration(-1)"]' or "")
        setting(name,"MouseScrollDownAction",show and '[!CommandMeasure AvatarUnlocks "GalleryScrollGeneration(1)"]' or "")
    end
end

local function drawGenerationMenu()
    local toggle="GalleryEvolution6"
    visible(toggle,true)
    setting(toggle,"Text",generations[generation].label..(generationMenuOpen and "  ▲" or "  ▼"))
    setting(toggle,"ToolTipText","포켓몬 세대 선택")
    setting(toggle,"SolidColor","212,226,210")
    setting(toggle,"LeftMouseUpAction","[!CommandMeasure AvatarUnlocks GalleryToggleGeneration()]")
    for i=0,#generations do
        local name="GalleryEvolution"..(7+i)
        visible(name,generationMenuOpen)
        if generationMenuOpen then
            setting(name,"Text",generations[i].label)
            setting(name,"ToolTipText",generations[i].label)
            setting(name,"SolidColor",i==generation and "179,212,186" or "230,238,226")
            setting(name,"LeftMouseUpAction",'[!CommandMeasure AvatarUnlocks "GallerySetGeneration('..i..')"]')
        end
    end
end

-- Reserve one row below the Pokémon grid without resizing the host window.
local function layoutGrid(compact)
    if compactGrid==compact then return end
    compactGrid=compact
    local size=compact and 46 or 64
    for n=1,9 do
        local cell="GalleryCell"..n
        local x=panelX+positions[cell][1]
        local y=panelY+positions[cell][2]-(compact and 12*math.floor((n-1)/3) or 0)
        setting(cell,"Y",y)
        local art="GalleryArt"..n
        setting(art,"X",x+(96-size)/2)
        setting(art,"Y",y+(compact and 3 or 5))
        setting(art,"W",size)
        setting(art,"H",size)
        setting("GalleryName"..n,"H",compact and 34 or 20)
        setting("GalleryLock"..n,"Y",y+5)
        setting("GalleryName"..n,"Y",y+(compact and 49 or 73))
    end
end

local function familyRuleReady(revision)
    return engine.isFamilyRuleReady(SKIN:GetVariable("UnlockAvatar"), revision)
end

local function evolutionCostHint(rule, ready)
    if not ready then return "가족 진화 비용 확인 대기" end
    return engine.stoneNames[rule.stone] .. " ×" .. rule.cost
end

local function levelHint(id, fallback, compact)
    if not familyRuleReady(engine.levelRevision) then
        return "가족 해금 레벨 확인 대기"
    end
    local level = levels[id]
    if not level then return fallback end
    if compact then return "Lv." .. level .. " 해금" end
    return "필요 레벨 " .. level
end

local function cell(n,item,owned,costReady)
    paint("GalleryCell"..n,1,0,0,96,compactGrid and 86 or 96,owned and "owned" or "locked")
    local art,lock,name="GalleryArt"..n,"GalleryLock"..n,"GalleryName"..n
    visible("GalleryCell"..n,not detail and (item~=nil or tab~=3))
    local wearable=tab==1 and owned and CanWearOutfit(item.id)
    local pet=tab==2 and owned and engine.pets[item.id]
    local click=((tab==3 and item) or wearable or pet) and ('[!CommandMeasure AvatarUnlocks "GallerySelect('..n..')"]') or ""
    for _,meter in ipairs({"GalleryCell"..n,art,lock,name}) do
        setting(meter,"LeftMouseUpAction",click)
    end
    visible(art,item~=nil)
    visible(lock,item~=nil and not owned)
    visible(name,item~=nil)
    if not item then setting("GalleryCell"..n,"ToolTipText","");return end
    local crop="64,192,12,12"
    if type(item.icon)=="number" and item.icon>=0 then
        crop=string.format("%d,%d,64,64",item.icon%9*64,math.floor(item.icon/9)*64)
    end
    local label=item.name or item.id
    local caption=label
    if tab==3 and item.dex then
        caption=dex(item.dex).."[\\x000a]"..label
        label=dex(item.dex).." "..label
    end
    local rule=tab==3 and engine.evolutions[item.id]
    local hint=owned and "해금 완료" or (rule and evolutionCostHint(rule, costReady) or
               levelHint(item.id, "해금 레벨 미정", false))
    if tab==3 then hint=hint..sizeSuffix(item.id) end
    if wearable then
        local worn=session:selected("outfit") or "tracksuit"
        if item.id==worn then
            caption=label.." · 착용 중"
            hint=item.id=="hoodie" and "클릭하여 벗기" or "기본 의상 착용 중"
        else
            hint="클릭하여 착용"
        end
    end
    if pet then
        local selected=session:selected("pet")==item.id
        caption=label..(selected and " · 산책 중" or "")
        hint=selected and "클릭하여 돌려보내기" or "클릭하여 바탕화면에 꺼내기"
    end
    setting(art,"ImageName",atlas)
    setting(art,"ImageCrop",crop)
    setting(art,"Greyscale",owned and 0 or 1)
    setting(art,"ImageAlpha",owned and 255 or 198)
    setting(name,"Text",caption)
    for _,meter in ipairs({"GalleryCell"..n,art,lock,name}) do
        setting(meter,"ToolTipText",label.." · "..hint)
    end
end

function G.refresh()
    if not active then return end
    local entries={}
    local range=generations[generation]
    local needle=query:lower()
    for _,item in ipairs(rows[kinds[tab]]) do
        local inGeneration=generation==0 or (item.dex and item.dex>=range.first and item.dex<=range.last)
        if tab~=3 or (inGeneration and matches(item,needle)) then entries[#entries+1]=item end
    end
    results=entries
    local family=detail and (families[memberFamily[detail.id]] or {}) or {}
    local parents={}
    for _,member in ipairs(family) do parents[member[1]]=member[3] end
    local pages=math.max(1,math.ceil(#entries/9))
    page=math.max(1,math.min(page,pages))
    local owned,count={},0
    for _,item in ipairs(entries) do
        if session and session:owns(item.id) then owned[item.id]=true;count=count+1 end
    end
    local costReady=familyRuleReady(engine.costRevision)
    local showSearch=tab==3 and not detail
    layoutGrid(showSearch)
    layoutGenerationMenu(showSearch)
    for n=1,9 do
        local item=entries[(page-1)*9+n]
        cell(n,not detail and item or nil,item and owned[item.id],costReady)
        local member=family[n]
        visible("GalleryEvolution"..n,member~=nil)
        if member then
            local id=member[2]
            local row="GalleryEvolution"..n
            local rule=engine.evolutions[id]
            local owned=session and session:owns(id)
            local status=owned and "보유" or (rule and evolutionCostHint(rule, costReady) or levelHint(id, "미해금", true))
            setting(row,"Text",dex(member[1]).." "..member[3].."   "..status)
            setting(row,"ToolTipText",(member[4] and parents[member[4]].." → " or "")..member[3]..sizeSuffix(id))
            setting(row,"SolidColor",picked==id and "185,224,190" or "0,0,0,1")
            setting(row,"W",286)
            setting(row,"LeftMouseUpAction",'[!CommandMeasure AvatarUnlocks "GalleryMember('..n..')"]')
        end
    end
    visible("GallerySearchFrame",showSearch)
    visible("GallerySearch",showSearch)
    visible("GalleryClear",showSearch and query~="")
    if showSearch then drawGenerationMenu() end
    visible("GalleryUpdates",not generationMenuOpen)
    visible("GalleryBack",true)
    setting("GalleryBack","FontFace",detail and "Galmuri9 Regular" or "Segoe UI Symbol")
    setting("GalleryBack","Text",detail and "목록으로" or "⚙")
    setting("GalleryBack","ToolTipText",detail and "목록으로" or "진화 비용·해금 레벨 설정")
    setting("GalleryBack","LeftMouseUpAction",detail and "[!CommandMeasure AvatarUnlocks GalleryBack()]" or "[!CommandMeasure AvatarUnlocks OpenCostEditor()]")
    visible("GalleryEmpty",tab==3 and ((not detail and #entries==0) or (detail and #family==0)))
    setting("GalleryEmpty","Text",detail and "등록된 진화 정보가 없어요" or "검색 결과가 없어요")
    local caption=query=="" and "포켓몬 이름 또는 도감 번호" or query
    -- The query is display text, never a Rainmeter variable or action.
    caption=caption:gsub("[#%[%]]",function(c) return string.format("[\\x%04x]",c:byte()) end)
    setting("GallerySearch","Text",caption)
    setting("GalleryTitle","Text",detail and (species[picked] and species[picked][3] or detail.name or detail.id) or "해금 도감")
    local rule=picked and engine.evolutions[picked]
    local owns=session and picked and session:owns(picked)
    local hint=picked and not rule and levelHint(picked, "진화 계열", true) or "진화 계열"
    local evolve=false
    if rule and not owns and not costReady then
        hint=evolutionCostHint(rule, false)
    elseif rule and not owns then
        local held=session and session.wallet.stones[rule.stone] or 0
        local parent=session and session:owns(rule.parent)
        hint=parent and (engine.stoneNames[rule.stone].." "..held.." / "..rule.cost) or "이전 포켓몬 필요"
        evolve=parent and held>=rule.cost and not session.wallet.error
    end
    setting("GalleryCount","Text",detail and hint or "해금 "..count.." / "..#entries)
    local canFollow=detail and picked and engine.walkRows[picked] and owns
    local rosterCount=session and session.roster and #session:roster() or 0
    local out=canFollow and (session.pokemonOut and session:pokemonOut(picked) or session:selected("pokemon")==picked)
    local full=canFollow and not out and rosterCount>=engine.roamLimit
    if canFollow then setting("GalleryCount","Text",hint.." · "..rosterCount.."/"..engine.roamLimit) end
    local followLabel=canFollow and (out and "돌려보내기" or (full and "6마리 가득" or "꺼내기"))
    setting("GalleryPageNumber","Text",followLabel or (rule and not owns and "진화") or (page.." / "..pages))
    setting("GalleryPageNumber","LeftMouseUpAction",canFollow and "[!CommandMeasure AvatarUnlocks GalleryCompanion()]" or evolve and "[!CommandMeasure AvatarUnlocks GalleryEvolve()]" or "")
    drawButtons(detail~=nil,page,pages,canFollow,evolve,rule~=nil)
    visible("GalleryPageNumber",canFollow or (detail and rule and not owns) or (not detail and pages>1))
    visible("GalleryPrev",not detail and page>1)
    visible("GalleryNext",not detail and page<pages)
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
    SKIN:Bang("!Redraw")
end

function G.init(resources,path,pokedex,pokemonSizes,coordinates)
    layoutPositions=coordinates
    bundled,cacheDir=resources.."unlock-gallery.png",path
    families=pokedex
    sizes=pokemonSizes
    for root,family in pairs(families) do
        for _,member in ipairs(family) do
            memberFamily[member[2]]=root
            species[member[2]]=member
        end
    end
end

function G.prepare()
    if next(positions) then return end
    for name,pos in pairs(layoutPositions) do positions[name]=pos end
    -- Keep both the Rainmeter search box and its native typing overlay clear of the selector.
    local frame=positions.GallerySearchFrame
    positions.GallerySearchFrame={frame[1],frame[2]-5}
    positions.GallerySearch={positions.GallerySearch[1],positions.GallerySearch[2]-5}
    positions.GalleryClear={213,positions.GalleryClear[2]-5}
    setting("GallerySearchFrame","Shape","Rectangle 1,1,213,28,6 | Fill Color 255,255,255 | Stroke Color 151,164,155 | StrokeWidth 1")
    setting("GallerySearch","W",157)
    place()
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
end

function G.bind(module,localItems,profile)
    if engine~=module or extras~=localItems then
        engine,extras=module,localItems
        catalogRows()
        atlas=nil
    end
    session=profile
    if active then atlas=atlas or imagePath();G.refresh() end
end

local function stopEditing()
    focusPending,retryAction=false,nil
    if editorFile then
        os.remove(editorFile)
        os.remove(editorFile..".focus")
        editorFile=nil
        SKIN:Bang("!DisableMeasure","GallerySearchWatch")
    end
end

function G.open(x,y)
    G.prepare()
    panelX,panelY=x,y
    if not active then place(x,y);placeButtons() end
    active=true
    atlas=atlas or imagePath()
    SKIN:Bang("!ShowMeterGroup","UnlockGallery")
    G.refresh()
end

function G.hide()
    if not active then return end
    active=false
    generation,generationMenuOpen=0,false
    detail,picked=nil,nil
    query,page="",1
    stopEditing()
    SKIN:Bang("!HideMeterGroup","UnlockGallery")
    place()
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
end

function G.tab(index)
    if not active or not kinds[index] then return end
    stopEditing()
    tab,page,detail,picked,query=index,1,nil,nil,""
    generationMenuOpen=false
    G.refresh()
end

function G.page(delta)
    if active and not detail and (delta==1 or delta==-1) then
        generationMenuOpen=false;page=page+delta;G.refresh()
    end
end

function G.toggleGeneration()
    if not active or tab~=3 or detail then return end
    generationMenuOpen=not generationMenuOpen
    if generationMenuOpen and editorFile then request("HIDE") end
    G.refresh()
end

function G.setGeneration(index)
    if not generationMenuOpen or not generations[index] then return end
    if generation~=index then page=1 end
    generation,generationMenuOpen=index,false
    G.refresh()
end

function G.scrollGeneration(delta)
    if not generationMenuOpen or (delta~=-1 and delta~=1) then return end
    local index=generation+delta
    if generations[index] then generation,page=index,1;G.refresh() end
end

function G.select(slot)
    if not active or detail then return end
    if tab==2 then
        local item=results[(page-1)*9+slot]
        if not item or not engine.pets[item.id] or not session or not session:owns(item.id) then return end
        local nextId=item.id
        if session:selected("pet")==item.id then nextId=nil end
        Choose("pet",nextId)
        ClosePanel()
        return
    end
    if tab==1 then
        local item=results[(page-1)*9+slot]
        if not item or not session or not session:owns(item.id) or not CanWearOutfit(item.id) then return end
        local id=item.id=="hoodie" and session:selected("outfit")~="hoodie" and "hoodie" or nil
        Choose("outfit",id)
        ClosePanel()
        return
    end
    if tab~=3 then return end
    detail=results[(page-1)*9+slot]
    if detail then generationMenuOpen=false;picked=detail.id;if editorFile then request("HIDE") end;G.refresh() end
end

function G.back()
    detail,picked=nil,nil
    G.refresh()
end

function G.member(slot)
    if not active or not detail then return end
    local member=(families[memberFamily[detail.id]] or {})[slot]
    if member then picked=member[2];G.refresh() end
end

function G.evolve()
    if not (active and detail and session and picked) then return end
    if familyRuleReady(engine.costRevision) then session:evolve(picked) end
    G.refresh()
end

function G.toggleCompanion()
    if not active or not detail or not session or not picked or not engine.walkRows[picked] or not session:owns(picked) then return end
    Choose("pokemon",picked)
    G.refresh()
end

function G.search(text)
    if not active or tab~=3 or detail then return end
    local value=text:match("^%s*(.-)%s*$")
    if value==query then return end
    query,page=value,1
    G.refresh()
end

request=function(action)
    local pos=positions.GallerySearch
    local x=(tonumber(SKIN:GetVariable("CURRENTCONFIGX")) or 0)+panelX+pos[1]
    local y=(tonumber(SKIN:GetVariable("CURRENTCONFIGY")) or 0)+panelY+pos[2]
    local width=math.max(10,SKIN:GetMeter("GallerySearch"):GetW())
    local clearMeter=SKIN:GetMeter("GalleryClear")
    local clearWidth=tonumber(clearMeter:GetOption("W")) or 25
    local clearX=positions.GalleryClear[1]-pos[1]-math.floor(clearWidth/2)
    local file=io.open(editorFile..".focus","wb")
    if not file then retryAction=action;return false end
    local nextEpoch=focusEpoch+1
    -- Focus commands can overtake each other between editor polls. Carry the
    -- last clear request in every command until the editor has applied it.
    local written=file:write(string.format("%d %d %s %d %d %d %d %d|",
        nextEpoch,clearGeneration,action,x,y,width,clearX,clearWidth))
    local closed=file:close()
    if written and closed then focusEpoch,retryAction=nextEpoch,nil;return true end
    retryAction=action
    return false
end

function G.clear()
    if generationMenuOpen then generationMenuOpen=false;G.refresh() end
    G.search("")
    if editorFile then
        clearGeneration=clearGeneration+1
        request("FOCUS")
    end
end

function G.edit()
    if not active or tab~=3 or detail then return end
    if generationMenuOpen then generationMenuOpen=false;G.refresh() end
    if editorFile then request("FOCUS");return end
    if editorRunning then focusPending=true;return end
    editorSequence=(editorSequence or 0)+1
    local token=editorInstance.."_"..editorSequence
    local path=os.getenv("TEMP").."\\FormdaySearch-"..token..".txt"
    local file=io.open(path,"wb")
    if not file then return end
    file:close()
    editorFile,editorRunning,focusEpoch,clearGeneration=path,token,0,0
    request("FOCUS")
    local hex=query:gsub(".",function(c) return string.format("%02X",c:byte()) end)
    -- Installed hosts carry an older editor in their INI. Launch the editor
    -- signed with the active engine, using only a generated token and hex seed.
    local parameter=[=[-NoLogo -NoProfile -STA -Command "$token=']=]..token..[=[';$seed=']=]..hex..[=[';& ([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(']=]..engine.searchScript..[=['))))"]=]
    SKIN:Bang("!SetVariable","GallerySearchToken",token)
    SKIN:Bang("!SetOption","GallerySearchEditor","Parameter",parameter)
    SKIN:Bang("!UpdateMeasure","GallerySearchEditor")
    SKIN:Bang("!CommandMeasure","GallerySearchEditor","Run")
    SKIN:Bang("!EnableMeasure","GallerySearchWatch")
end

function G.tick()
    if not editorFile then return end
    if retryAction and not request(retryAction) then return end
    if detail then return end
    local file=io.open(editorFile,"rb")
    if not file then return end
    local record=file:read(420)
    file:close()
    if not record then return end
    local epoch,hex=record:match("^QUERY:(%d+):(%x*)|$")
    if tonumber(epoch)==focusEpoch and #hex%2==0 and #hex<=384 then
        G.search((hex:gsub("%x%x",function(b) return string.char(tonumber(b,16)) end)))
    end
end

function G.edited(output)
    local token=output:match("CLOSED ([%w_]+)")
    if token and token~=editorRunning then return end
    local reopen=focusPending
    stopEditing()
    editorRunning=nil
    if reopen then G.edit() end
end

function G.shutdown() stopEditing() end

return G

end
function M.createFollower()
-- The first gallery image and the live-search timer are free while the book is
-- closed. Reuse them so installed skins can gain a follower through the catalog.
local F={}
local meter,clock="GalleryArt1","GallerySearchWatch"
local id,tier,row,box,scale,width,height,atlas,anchorName
local paused,armed=false,false
local lastX,distance,direction,ground=nil,0,1,nil
local crop,px,py,rearOffsets
local panelHome,panelShift=nil,0
-- The currently installed Formday hosts place these controls beside the actor.
-- Leave their original hit boxes and alignment intact when the catalog is open.
local panelMeters=[[CompactCard CompactTitle CompactState DotWorkout RowWorkout CountWorkout
DotCalories RowCalories CountCalories DotProtein RowProtein CountProtein DotBody RowBody CountBody
InfoCard InfoTitle InfoClose ProgressValue Remaining Completed RecordState OpenFolder Unload OpenSite
GameMode ConnectSite ConnectFolder CopySyncFolder UpdateButtonBg UpdateButton UpdateNote InfoGear PowderIcon PowderBalance OpenWorkshopButton
SettingsCard SettingsTitle SettingsBack SettingsHint SettingsStartupRow SettingsStartupName SettingsStartupValue
SettingsWalkRow SettingsWalkName SettingsWalkValue SettingsBadgeRow SettingsBadgeName SettingsBadgeValue]]

panelMeters=panelMeters.." CraftCard CraftTitle CraftBack CraftPowderIcon CraftPowder CraftCost CraftHeld"
for i=1,#M.stoneOrder do
    panelMeters=panelMeters.." CraftIcon"..i.." CraftName"..i.." CraftStock"..i.." CraftButton"..i
end

local function placePanel(rightEdge)
    if not panelHome then
        panelHome={}
        if not SKIN:GetMeter("CompactCard") then return end
        for name in panelMeters:gmatch("%S+") do
            local control=SKIN:GetMeter(name)
            if control then panelHome[name]=tonumber(control:GetOption("X")) or control:GetX() end
        end
    end
    if not panelHome.CompactCard then return end
    local shift=math.max(0,rightEdge-panelHome.CompactCard)
    if shift==panelShift then return end
    for name,home in pairs(panelHome) do
        SKIN:Bang("!SetOption",name,"X",tostring(home+shift))
        SKIN:Bang("!UpdateMeter",name)
    end
    panelShift=shift
end

local front="GalleryArt1"
function F.active() return armed end
local rear,home,actorShift,coverPose
local function option(target,name,value)
    SKIN:Bang("!SetOption",target,name,tostring(value))
end

-- Reserve just enough space inside the left window edge for a complete sprite.
local function placeActor(shift)
    if actorShift==shift then return end
    for name,position in pairs(home) do
        option(name,"X",shift==0 and position.raw or position.x+shift)
        SKIN:Bang("!UpdateMeter",name)
    end
    actorShift=shift
end

local function prepareLayout()
    home={}
    local companions=SKIN:GetVariable("UnlockFollowerAnchorMeters") or "Level UpdateBalloon UpdateSpeech"
    for name in (anchorName.." "..companions):gmatch("%S+") do
        local control=SKIN:GetMeter(name)
        if control then home[name]={x=tonumber(control:GetOption("X")) or control:GetX(),raw=control:GetOption("X",tostring(control:GetX()),false)} end
    end
    actorShift=0
    meter=front
    if tier~="large" then return end
    local back=SKIN:GetVariable("UnlockFollowerBackMeter")
    if not back or back=="" then
        back=SKIN:GetMeter("UnlockFollowerBack") and "UnlockFollowerBack" or "CompactBounds"
    end
    local host=SKIN:GetMeter(back)
    if host and host:GetOption("Meter",""):lower()=="image" and host:GetOption("ImageName","")=="" then
        meter=back
        rear={x=host:GetX(),y=host:GetY(),w=host:GetW(),h=host:GetH(),options={}}
        for _,key in ipairs({"X","Y","W","H","Padding","ImageName","ImageCrop","Hidden"}) do
            rear.options[key]=host:GetOption(key,"",false)
        end
    end
end

-- A custom host without an earlier empty image can reproduce its animated
-- avatar above the follower with the next unused gallery image.
local function updateCover(actor,ax,ay,w,h)
    if tier~="large" or rear then return end
    local m="GalleryArt2"
    if not SKIN:GetMeter(m) then return end
    local image=actor:GetOption("ImageName","")
    local flip=actor:GetOption("ImageFlip","None")
    local frame=actor:GetOption("ImageCrop","")
    local key=table.concat({image,flip,frame,ax,ay,w,h},"|")
    if key==coverPose then return end
    coverPose=key
    for k,v in pairs({ImageName=image,ImageFlip=flip,ImageCrop=frame,X=ax,Y=ay,W=w,H=h,
                      ImageAlpha=255,Greyscale=0,ToolTipText="",LeftMouseUpAction=""}) do option(m,k,v) end
    SKIN:Bang("!ShowMeter",m)
    SKIN:Bang("!UpdateMeter",m)
end

local function set(name,value) SKIN:Bang("!SetOption",meter,name,tostring(value)) end

local function stop()
    if not armed then return end
    armed=false
    if rear then
        for key,value in pairs(rear.options) do option(meter,key,value) end
        SKIN:Bang(rear.options.Hidden=="1" and "!HideMeter" or "!ShowMeter",meter)
        SKIN:Bang("!UpdateMeter",meter)
        rear=nil
    elseif coverPose then
        option("GalleryArt2","ImageFlip","None")
        SKIN:Bang("!HideMeter","GalleryArt2")
        SKIN:Bang("!UpdateMeter","GalleryArt2")
    end
    meter,coverPose=front,nil
    placeActor(0)
    placePanel(0)
    SKIN:Bang("!DisableMeasure",clock)
    SKIN:Bang("!SetOption",clock,"OnUpdateAction","[!CommandMeasure AvatarUnlocks GallerySearchTick()]")
    SKIN:Bang("!HideMeter",meter)
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

local function start()
    if armed or paused or not row or not SKIN:GetMeter(anchorName) then return end
    armed=true
    lastX,distance,crop,px,py,ground=nil,0,nil,nil,nil,nil
    prepareLayout()
    set("ImageName",atlas)
    set("W",width);set("H",height)
    if not rear then
        set("Greyscale",0);set("ImageAlpha",255)
        set("ToolTipText","");set("LeftMouseUpAction","")
    end
    SKIN:Bang("!SetOption",clock,"OnUpdateAction","[!CommandMeasure AvatarUnlocks FollowerTick()]")
    SKIN:Bang("!EnableMeasure",clock)
    F.tick()
    SKIN:Bang("!ShowMeter",meter)
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

function F.select(nextId,nextTier,nextScale,anchor,cacheDir,resources,offsets)
    if nextId~=id or nextTier~=tier or nextScale~=scale or anchor~=anchorName then
        stop()
        id,tier,scale,anchorName,rearOffsets=nextId,nextTier,nextScale,anchor,offsets
        row=id and M.walkRows[id]
        if row then
            box=M.walkCrops[row+1]
            local pixelScale=scale*box.referenceHeight/box.h
            width=math.max(1,math.floor(box.w*pixelScale+0.5))
            height=math.max(1,math.floor(box.h*pixelScale+0.5))
            if not atlas then atlas=M.imageFile(cacheDir,"unlock-walk",M.walkAtlas,resources.."unlock-walk.png") end
        end
    end
    start()
end

function F.panel(open)
    paused=open
    if open then stop() else start() end
end

function F.tick()
    if not armed then return end
    local actor=SKIN:GetMeter(anchorName)
    if not actor then return end
    local ax,ay,w,h=actor:GetX(),actor:GetY(),actor:GetW(),actor:GetH()
    local inset=math.floor(w*0.42+0.5)
    local origin=home[anchorName].x
    local shift=tier=="small" and math.max(0,width+2-origin-inset) or 0
    placeActor(shift)
    ax=origin+shift
    local x=tonumber(SKIN:GetVariable("CURRENTCONFIGX")) or 0
    local dx=lastX and (x-lastX) or 0
    lastX=x
    if dx~=0 then direction=dx>0 and 1 or -1 end
    if dx==0 then distance=0 else distance=(distance+math.abs(dx))%(box.cycle or 16) end
    local density=box.density
    local cx,cy
    if box.ends then
        local frame=0
        while distance>=box.ends[frame+1] do frame=frame+1 end
        cx=frame*box.w*density
        cy=box.stripY+(direction>0 and box.h*density or 0)
    else
        local frame=math.floor(distance/4)
        cx=math.floor(row/8)*128*M.walkDensity+(frame*32+box.x)*density
        cy=(row%8)*64*M.walkDensity+((direction>0 and 32 or 0)+box.y)*density
    end
    local nextCrop=string.format("%d,%d,%d,%d",cx,cy,box.w*density,box.h*density)
    local footInset=tonumber(SKIN:GetVariable("UnlockFollowerFootInset"))
        or (SKIN:GetVariable("UnlockAvatar")=="formday-buddy" and 3 or 0)
    if not ground or SKIN:GetVariable("Pose")~="jump" then ground=ay+h-footInset end
    local nextX,nextY,panelRight
    if tier=="small" then
        nextX,nextY=ax+inset-width,ground-height+math.floor(h*0.065+0.5)
    elseif tier=="large" then
        local offset=0.49
        if rearOffsets then
            offset=direction<0 and rearOffsets.left or rearOffsets.right
            -- Keep the adjacent controls still when the follower turns its head.
            panelRight=ax+math.floor(w*math.max(rearOffsets.left,rearOffsets.right)+0.5)+width
        end
        nextX,nextY=ax+math.floor(w*offset+0.5),ground-height-math.floor(h*0.08+0.5)
    else
        nextX,nextY=ax+math.floor(w*0.73+0.5),ground-height
    end
    nextX,nextY=math.max(0,nextX),math.max(0,nextY)
    placePanel(math.max(ax+w,panelRight or nextX+width)+8)
    updateCover(actor,ax,ay,w,h)
    if crop==nextCrop and px==nextX and py==nextY then return end
    if crop~=nextCrop then set("ImageCrop",nextCrop) end
    if rear then
        if px~=nextX or py~=nextY then
            -- Padding keeps the original transparent skin bounds and hit origin.
            set("X",0);set("Y",0)
            set("Padding",table.concat({nextX,nextY,math.max(0,rear.x+rear.w-nextX-width),
                                       math.max(0,rear.y+rear.h-nextY-height)},","))
        end
    else
        if px~=nextX then set("X",nextX) end
        if py~=nextY then set("Y",nextY) end
    end
    crop,px,py=nextCrop,nextX,nextY
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

return F

end
