local function follow(sample)
    local target=SKIN:GetVariable("PetGoal") or ""
    local gx,gy=target:match("^(-?%d+),(-?%d+)$")
    if not gx then return end
    local l,t,r,b=limits()
    gx,gy=math.max(l,math.min(r,tonumber(gx))),math.max(t,math.min(b,tonumber(gy)))
