 local cx,cy
 if strip>=0 then
  local f=0
  while values[14+f] and n>=values[14+f] do f=f+1 end
  cx,cy=f*w*d,strip+(dir>0 and h*d or 0)
 else
  local f=math.floor(n/4)
  cx=math.floor(row/8)*128*g+(f*32+bx)*d
  cy=(row%8)*64*g+((dir>0 and 32 or 0)+by)*d
 end
 local crop=table.concat({cx,cy,w*d,h*d},",")
 if crop~=lastCrop then
  SKIN:Bang("!SetOption","Sprite","ImageCrop",crop); SKIN:Bang("!UpdateMeter","Sprite");lastCrop=crop
 end
end
function Hover(active)
 hovered=active==1
 if hovered then grabGrace=8 else settle=8 end
end
function RequestReturn()
 if not token then return end
 local f=io.open(privatePath.."return."..token..".txt","wb");if not f then return end
 f:write("return\n");f:close()
end
local function position(name,px,py)
