local childSkin=(""):gsub("..",function(pair) return string.char(tonumber(pair,16)) end)
local function changed(path,body)
 local f=io.open(path,"rb");if not f then return nil end
 local old=f:read("*a");f:close()
 if old==body then return true end
 if write(path,body) then return true end
 write(path,old)
