end
function M.createPet()
-- The selected pet is a second native Rainmeter config, with its own window and input.
local P={}
local root=SKIN:GetVariable("CURRENTPATH")
local folder=root.."FormdayDesktopPet\\"
local config=SKIN:GetVariable("CURRENTCONFIG").."\\FormdayDesktopPet"
local lease=root.."FormdayKirby.active"
local selected,prepared,nextPulse,nextFolder=nil,false,0,0
local function read(path)
    local f=io.open(path,"rb");if not f then return nil end
    local s=f:read("*a");f:close();return s
end
local function write(path,data)
    local f=io.open(path,"wb");if not f then return false end
    local ok=f:write(data)
    return f:close() and ok
end
local function prepare(now)
    local pet=M.pets[selected]
    -- Keep the registered skin variant so previously installed copies can switch in place.
    local iniPath=folder.."Kirby.ini"
    local prior=read(iniPath)
    local script="motion-"..selected.."-"..M.version..".lua"
    if read(folder..script)~=pet.window and not write(folder..script,pet.window) then
        if now>=nextFolder then
            nextFolder=now+10
            -- Only create this skin's own child directory; all animation runs in Rainmeter.
            local target=folder:sub(1,-2):gsub("'","''")
            local ps=os.getenv("SystemRoot").."\\System32\\WindowsPowerShell\\v1.0\\powershell.exe"
            SKIN:Bang('["'..ps..'" -NoProfile -NonInteractive -WindowStyle Hidden -Command "[void][IO.Directory]::CreateDirectory(\''..target..'\')"]')
        end
        return false
    end
    local image=selected.."-"..M.version..".png"
    if M.imageFile(folder,selected,pet.atlas,"")~=folder..image then return false end
    local ini=M.petIni:gsub("@SCRIPT@",script):gsub("@IMAGE@",image):gsub("@WIDTH@",tostring(pet.width))
    if pet.ink then
        local inkName=selected.."-ink"
        local inkPath=M.imageFile(folder,inkName,pet.ink,"")
        if inkPath=="" then return false end
        ini=ini.."\n[Ink]\nMeter=Image\nX=60\nY=0\nW=80\nH=86\nHidden=1\nImageCrop=60,0,80,86\nImageName=#CURRENTPATH#"..inkName.."-"..M.version..".png\n"
    end
    if prior~=ini and not write(iniPath,ini) then return false end
    prepared=true
    if not prior then
        -- Only the initial installation needs to register the new skin folder.
        SKIN:Bang("!RefreshApp")
    else
        SKIN:Bang("!ActivateConfig",config,"Kirby.ini")
        if prior~=ini then SKIN:Bang("!Refresh",config) end
    end
    return true
end
function P.pulse()
    if not selected then return end
    local now=os.time()
    if now<nextPulse and now>=nextPulse-4 then return end
    nextPulse=now+(prepared and 4 or 1)
    if not write(lease,M.version.."|"..now.."|"..selected.."\n") then return end
    if not prepared then prepare(now) end
end
local px,py,lastGoalAt
function P.active() return selected end
function P.track()
    if not selected or not prepared then return end
    local a=SKIN:GetMeter("Avatar");if not a then return end
    local x=(tonumber(SKIN:GetVariable("CURRENTCONFIGX")) or 0)+a:GetX()-90
    local y=(tonumber(SKIN:GetVariable("CURRENTCONFIGY")) or 0)+a:GetY()+a:GetH()-86
    x,y=math.floor(x+0.5),math.floor(y+0.5)
    local now=os.time()
    -- Resend the goal to a newly loaded or refreshed child even while standing still.
    if x~=px or y~=py or now~=lastGoalAt then
        local target=tostring(x)..","..tostring(y)
        SKIN:Bang("!SetVariable","PetGoal",target,config)
        px,py,lastGoalAt=x,y,now
    end
end

function P.select(id)
    local show=id and M.pets[id] and id or nil
    if show==selected then return end
    selected=show
    if show then
        px,py=nil,nil
        prepared,nextPulse=false,0
        P.pulse()
    else
        write(lease,"off\n")
        if prepared then SKIN:Bang("!DeactivateConfig",config) end
        prepared=false
    end
end
function P.shutdown()
    if selected then write(lease,"off\n") end
end
return P

end

local function key(value)
    return type(value) == "string" and #value <= 48 and value:match("^[a-z0-9][a-z0-9_-]*$") ~= nil
end

local function exists(path)
    local f = io.open(path,"rb")
    if f then f:close(); return true end
    return false
end

local base64={}
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i=1,#alphabet do base64[alphabet:byte(i)]=i-1 end
local function decodeQuartet(group)
    local a,b,c,d=group:byte(1,4)
    local value=((base64[a]*64+base64[b])*64+(base64[c] or 0))*64+(base64[d] or 0)
    local first=math.floor(value/65536)
    if c==61 then return string.char(first) end
    local second=math.floor(value/256)%256
    if d==61 then return string.char(first,second) end
    return string.char(first,second,value%256)
end

function M.imageFile(cacheDir,name,encoded,bundled)
    local path=cacheDir..name.."-"..M.version..".png"
    if exists(path) then return path end
    local temp=path.."."..tostring({}):gsub("[^a-zA-Z0-9]","")..".tmp"
    local file=io.open(temp,"wb")
    if file then
        local bytes=encoded:gsub("....",decodeQuartet)
        local written=file:write(bytes)
        local closed=file:close()
        if written and closed and os.rename(temp,path) then return path end
        os.remove(temp)
        if exists(path) then return path end
    end
    return bundled
end

-- Per-avatar signed rules take precedence over bundled copies from older skins.
function M.isFamilyAvatar(avatar)
    return avatar=="formday-buddy" or avatar=="formday-geo"
end
function M.isFamilyRuleReady(avatar, revision)
    return not M.isFamilyAvatar(avatar) or revision ~= nil
end

function M.catalogFor(avatar,localCatalog)
    local rules=M.avatarRewards[M.isFamilyAvatar(avatar) and "formday-buddy" or avatar] or {}
    local result,signed={},{}
    for _,item in ipairs(rules) do
        result[#result+1]=item
        signed[item.id]=item.kind
    end
    for _,item in ipairs(localCatalog) do
        if not signed[item.id] then result[#result+1]=item
        else assert(signed[item.id]==item.kind,"reward kind changed") end
    end
    return M.withFamilyLevels(result)
end

function M.connect(dataPath, avatar, profile, catalog)
    assert(key(avatar) and key(profile), "invalid avatar or profile")
    local prefix = dataPath .. "unlock~" .. avatar .. "~" .. profile .. "~"
    local pending = prefix .. tostring({}):gsub("[^a-zA-Z0-9]", "") .. "-" .. os.time() .. ".tmp"
    local index, ordered = {}, {}
    local function register(item)
        assert(key(item.id) and key(item.kind) and type(item.level)=="number" and item.level >= 1
            and item.level==math.floor(item.level) and not index[item.id], "invalid reward catalog")
        index[item.id]=item
        if item.kind~="pokemon" or not M.evolutions[item.id] then ordered[#ordered+1]=item end
    end
    for _,item in ipairs(M.catalog) do register(item) end
    for _,item in ipairs(M.catalogFor(avatar,catalog)) do register(item) end
    table.sort(ordered,function(a,b) if a.level==b.level then return a.id<b.id end return a.level<b.level end)
    local session = {}
    M.attachWallet(session,prefix,pending..".wallet")
    local function kindOf(id)
        return (index[id] and index[id].kind) or (M.evolutions[id] and "pokemon") or M.levelKinds[id]
    end
    function session:owns(id)
        return session.wallet.forms[id] == true or (kindOf(id) ~= nil) and exists(prefix .. id .. ".owned")
    end
    function session:sync(level)
        assert(type(level)=="number" and level>=1 and level==math.floor(level),"invalid level")
        local added = {}
        for _,item in ipairs(ordered) do
            if item.level>level then break end
            local path = prefix .. item.id .. ".owned"
            if not exists(path) then
                local file = assert(io.open(pending,"wb"))
                local written = file:write(item.id,"\n")
                local closed = file:close()
                assert(written and closed,"reward save failed")
                -- On Windows rename creates the receipt only if no other instance won.
                if os.rename(pending,path) then added[#added+1]=item.id
                else os.remove(pending); assert(exists(path),"reward commit failed") end
            end
        end
        return added
    end
    function session:selected(kind)
        assert(key(kind),"invalid reward kind")
        local file=io.open(prefix..kind..".selection","rb")
        if not file then return nil end
        local last
        for line in file:lines() do
            local id=line:match("^=([a-z0-9_-]*)!$")
            if id then last=id end
        end
        file:close()
        if kindOf(last)==kind and self:owns(last) then return last end
    end
    function session:select(kind,id)
        assert(key(kind) and (id==nil or (kindOf(id)==kind and self:owns(id))),"reward unavailable")
        if self:selected(kind)==id then return end
        local file=assert(io.open(prefix..kind..".selection","ab"))
        local written=file:write("\n="..(id or "").."!\n")
        local closed=file:close()
        assert(written and closed,"selection save failed")
    end
    local rosterFile=prefix.."pokemon-roster.selection"
    function session:roster()
        local record
        local f=io.open(rosterFile,"rb")
        if f then
            for line in f:lines() do
                if line:match("^=[a-z0-9_,-]*!$") then record=line:sub(2,-2) end
            end
            f:close()
        end
        if record==nil then record=self:selected("pokemon") or "" end
        local out,seen={},{}
        for id in record:gmatch("[^,]+") do
            if not seen[id] and M.walkRows[id] and kindOf(id)=="pokemon" and self:owns(id) and #out<M.roamLimit then
                out[#out+1]=id;seen[id]=true
            end
        end
        return out
    end
    function session:pokemonOut(id)
        for _,out in ipairs(self:roster()) do if out==id then return true end end
        return false
    end
    function session:togglePokemon(id)
        if not id or not M.walkRows[id] or kindOf(id)~="pokemon" or not self:owns(id) then return false end
        local roster=self:roster()
        local removed=false
        for i,out in ipairs(roster) do
            if out==id then table.remove(roster,i);removed=true;break end
        end
        if not removed then
            if #roster>=M.roamLimit then return false end
            roster[#roster+1]=id
        end
        local f=io.open(rosterFile,"ab");if not f then return false end
        local written=f:write("\n="..table.concat(roster,",").."!\n")
        return f:close() and written~=nil
    end
    return session
end
-- Older kits already load verified engines as Lua modules. Switch only the gallery
-- measure to the signed shared file. The host's skin and update service stay independent.
if SKIN and SELF then
    if SKIN:GetMeter("GallerySearchFrame") and SELF:GetName()=="AvatarUnlocks" then
        local dir=os.getenv("LOCALAPPDATA").."\\FormdayAvatar\\Unlocks\\v1\\"
